\label{thm:main}
Let $F$ be a field of characteristic zero. Every polynomial
$f\in F[x,y,z]$ satisfying \eqref{eq:intro-cyclic} and
\eqref{eq:intro-norm} can be written as
\begin{equation}\label{eq:intro-decomposition}
 f(x,y,z)=P(x,y)+Q(y,z)+R(z,x),\qquad P,Q,R\in F[X,Y].
\end{equation}
Equivalently, $f$ satisfies $\partial_x\partial_y\partial_z f=0$.
Every homogeneous solution of odd degree is zero.

\label{thm:symmetric-classification}
Let $n\ge0$ be even. A symmetric polynomial $f\in F[x,y,z]_n$ satisfies
\eqref{eq:intro-norm} if and only if
\begin{equation}\label{eq:main-classification}
 f=\Phi(q),
\end{equation}
where $q\in F[X,Y]_n$ is symmetric, odd in each variable, and satisfies
\begin{equation}\label{eq:binary-period-intro}
 q(X,Y)+q(-Y,X-Y)+q(Y-X,-X)=0.
\end{equation}
The binary polynomial is uniquely $q(X,Y)=f(X,Y,0)$.

\label{cor:complete-periods}
For every $n\ge0$, restriction is an $F$-linear isomorphism
\begin{equation}\label{eq:period-restriction}
 W_n(F)\longrightarrow\mathscr P_n^0(F),\qquad f\longmapsto f(X,Y,0).
\end{equation}
Its inverse is $q\mapsto\Phi(q)$. It identifies
$W_n^{\mathrm{sym}}(F)$ with $\mathscr P_n^{0,\mathrm{odd}}(F)$ and
$W_n^{\mathrm{alt}}(F)$ with $\mathscr P_n^{0,\mathrm{ev}}(F)$.

\label{cor:dimensions}
For every even $n>0$, the period maps induce complex linear isomorphisms
\[
 W_n^{\mathrm{sym}}(\mathbb C)\cong S_{n+2},\qquad
 W_n^{\mathrm{alt}}(\mathbb C)\cong S_{n+2}.
\]
For every characteristic zero field $F$ and every $n\ge0$, we have
\begin{equation}\label{eq:dimensions}
 \dim_F W_n^{\mathrm{sym}}(F)=\dim_F W_n^{\mathrm{alt}}(F)
   =\dim_{\mathbb C}S_{n+2}.
\end{equation}
All these spaces vanish when $n=0$ or $n$ is odd. Consequently, the generating function of the dimensions is
\begin{equation}\label{eq:W-Hilbert}
 \sum_{n\ge0}\dim_F W_n(F)t^n=\frac{2t^{10}}{(1-t^4)(1-t^6)}.
\end{equation}

\label{lem:sym-boundary-factors}
A symmetric homogeneous solution $f$ is divisible by $c_+$. In positive even
degree it is divisible by $wc_+$.

\label{lem:period-extraction}
Let $m>0$ be odd and let $v\in V_m$ be symmetric. Then we have
\begin{equation}\label{eq:common-kernel}
 J_v=0\quad\Longleftrightarrow\quad
 v\in\bigoplus_{j\ge0}w^{2j}L(\mathcal B_{m+1-2j}).
\end{equation}
Every lift on the right is polynomial, and the expression is unique.

\label{cor:period-towers}
If a symmetric solution $f\in V_n$ satisfies $J_f=0$, then uniquely
\begin{equation}\label{eq:sym-tower}
 f=\sum_{j\ge0}w^{e_j}\Phi(q_j),\qquad
 \begin{cases}
 e_j=2j,\ q_j\in\mathcal B_{n-2j},& n\text{ even},\\
 e_j=2j-1,\ q_j\in\mathcal B_{n+1-2j},& n\text{ odd}.
 \end{cases}
\end{equation}
The sum is finite. In odd degree, its first term is interpreted as the
polynomial lift $L(q_0)$.

\label{prop:26-model}
The group $H_3(K,E_{n,t})$, with the right coefficient action defined above,
is represented by precisely the functions $F:\mathcal S\to V_n$ such that
\begin{align}
 &F(rh)=\chi_t(h)F(r)\mid h,\label{eq:fiber-signed}\\
 &F(r)+F(rA^2)\mid A+F(rA)\mid A^2=0,\label{eq:fiber-norm}
\end{align}
for every $r\in\mathcal S$ and every signed permutation matrix $h$.
Every bar in \eqref{eq:fiber-signed}--\eqref{eq:fiber-norm} is untwisted.
The determinant factor has already been included in $\chi_t$.
The coordinate $F(\ell)$ is the value on the identity apartment of the
corresponding ordinary Steinberg functional.

\label{lem:apartment-boundary-pairing}
Let $j$ be the inclusion of the boundary, and let
$\operatorname{PD}_{\partial}:H_3(\partial\overline{\mathscr X}_G;\mathcal M)
\to H^1(\partial\overline{\mathscr X}_G;\mathcal M)$
be boundary Poincar\'e duality. The diagram
\begin{equation}\label{eq:apartment-boundary-diagram}
\begin{CD}
 H_3(\partial\overline{\mathscr X}_G;\mathcal M)
       @>{j_*}>> H_3(\overline{\mathscr X}_G;\mathcal M)\\
 @V{\operatorname{PD}_{\partial}}VV
       @VV{z\mapsto\varphi(F_z)}V\\
 H^1(\partial\overline{\mathscr X}_G;\mathcal M)
       @>{\omega\mapsto\langle\omega,\partial a_\varphi\rangle}>>\mathbb Q
\end{CD}
\end{equation}
commutes. In particular, for $\lambda\in V_n^*$ and
$\varphi_\lambda(F)=\lambda(F(\ell))$, we have
\begin{equation}\label{eq:apartment-boundary-evaluation}
 \lambda\bigl(F_{j_*c}(\ell)\bigr)
    =\bigl\langle\operatorname{PD}_{\partial}c,
                     \partial a_{\varphi_\lambda}\bigr\rangle.
\end{equation}
This is compatible with induction of coefficients and with
passage to a finite index subgroup.

\label{thm:boundary-evaluation}\label{prop:top-is-boundary}
If $n>0$, every $K$-equivariant map $\operatorname{St}\to E_{n,t}$ takes the identity
apartment into $U_n$, for $t=0,1$.

\label{lem:three-seed}
A signed-permutation equivariant function $F$ as in
\eqref{eq:fiber-signed} is uniquely determined by its seeds
$P=F(1,0,0)$, $Q=F(1,1,0)$, and $f=F(1,1,1)$.
Such an $F$ satisfies \eqref{eq:fiber-norm} if and only if the seeds satisfy
\begin{gather*}
 f\text{ symmetric},\quad Q(a,b,c)=Q(b,a,c)=-Q(a,b,-c),\\
 P(a,b,c)=P(a,c,b)=-P(a,-b,c)=-P(a,b,-c),\\
 N_{12}f=N_{12}Q=N_{23}P=0,
\end{gather*}
and
\begin{align}
 Q(a,b,c+a)-Q(a,b,c)&=f(a+c,-c,b),\label{eq:mixed1}\\
 P(a,c+a,b)-P(a,c,b)&=Q(-c,a+c,b).\label{eq:mixed2}
\end{align}
Conversely, seeds with these properties extend uniquely by
\eqref{eq:fiber-signed} to a function satisfying both fiber equations.
The statement holds for polynomial or rational function coefficients.

\label{mf:lem:kernel}
The ring $R=k[d_4,d_6,d_7]$ is a polynomial ring. On symmetric polynomials,
$\ker\overline N$ is a free $R$-module on $K_j=aC_+ B_j$, $0\le j<8$, where
\begin{equation}\label{mf:eq:Bs}
\begin{split}
(B_0,\ldots,B_7)=\bigl(&1,a,a^2+b,ab,a^3+c,aC_+,\\
                     &a^3(a^2+b),a^6+a^3c+b^3+c^2\bigr).
\end{split}
\end{equation}

\label{mf:lem:well-defined}
The maps $\beta_\pm$ are independent of the respective choices of lift and
are $R_2$-linear.

\label{mf:lem:beta}
On the odd reduced norm kernel, we have
\begin{equation}\label{mf:eq:beta-result}
 \beta_+(v)=U(v),\qquad \beta_-(v)=v+U(v).
\end{equation}
Moreover, we have $U^3=0$.

\label{prop:coefficient-base-change}
For every commutative $\mathbb Q$-algebra $R$ and every $n\ge0$, the natural maps
\begin{equation}\label{eq:coefficient-base-change}
\begin{split}
 R\otimes_{\mathbb Q}W_n&\xrightarrow{\ \sim\ }W_n(R) \qquad {\text {and}}\qquad
 R\otimes_{\mathbb Q}\mathscr P_n^0\xrightarrow{\ \sim\ }\mathscr P_n^0(R)
\end{split}
\end{equation}
are isomorphisms. The same statement holds for the symmetric and alternating
solution spaces and for the even and odd period spaces. The ambient
coefficient-extension maps commute with restriction to a coordinate plane
and with cyclic summation.

\label{lem:literal-residue-comparison}
With compatible orientation and averaging normalizations, the diagram
\begin{equation}\label{eq:residue-comparison-diagram}
\begin{CD}
 H_3(G,\mathcal R_n\otimes\det)
     @>{\mathrm{Sh}}>>H_3(P_H,\mathcal R_{n,H}\otimes\det)\\
 @V{\operatorname{res}_H}VV @VV{\kappa}V\\
 \mathcal B_{n+1}
     @< {\operatorname{edge}_2}<<H_1(\mathrm{GL}_2(\mathbb Z),D_{n+1})
\end{CD}
\end{equation}
commutes. Changing these normalizations multiplies the comparison by one
fixed nonzero scalar, independent of the polynomial. In particular, it does
not mix its coefficients. The composite identifies the residue with the
usual odd period polynomial in the same variables $b,c$.

\label{ar:lem:stokes}
Suppose $a\in H^2(X_\Gamma,E)$ and $b\in H^2(X_\Gamma,E^*)$ have only
mixed cuspidal restrictions on maximal faces and zero restrictions on all
flag strata. Then, we have
\begin{equation}\label{ar:eq:stokes}
 \langle r_Pa,r_Pb\rangle_P+\langle r_Qa,r_Qb\rangle_Q=0.
\end{equation}
The orientations are included in the two pairings.

\label{ar:prop:convergence}
The series \eqref{ar:eq:Eseries} converges normally with every derivative
on compact subsets of $\mathscr X$. It defines a closed global two-form.
